INSERT INTO releases (version, released_on, title, public_notes, tech_notes) VALUES (
  '2.96.1',
  '2026-09-22',
  'Пульт ТВ: прогресс на панели музыки и починенный переход между треками',
  E'Полоску прогресса больше не нужно искать в окне плейлиста: она всегда видна тонкой линией по верхнему краю панели музыки (и в панели рядом с плеером). В самом окне плейлиста полоска стала тоньше.\n\nИ починили плавный переход: раньше в конце трека успевало прозвучать начало следующего, потом всё сбрасывалось, и он начинался заново.',
  E'player.html. Прогресс: updateQueueProgress() теперь обновляет и тонкие полоски .mprog на #vmusic и в панели #music (не только окно очереди), зовётся и из updateMusicLine; высота полоски в окне 8 → 4 px.\n\nПереход: элементы меняются местами по времени — в обработчике timeupdate при rem <= 0,25 с зовётся finishFade(), а не только по событию ended. Chrome в конце трека присылает «pause» (порядок с «ended» не гарантирован), и обработчик паузы отменял переход: подготовленный элемент глушился, затем ended уводил в musicStep(1, true) → playMusic() → следующий трек с нуля. Теперь пауза с e.target.ended переход не отменяет, а ended остаётся запасным путём, если последнего timeupdate не пришло.\n\nПроверено в браузере на подменённых элементах: оба порядка событий в конце трека (pause→ended и ended→pause) — обмен элементами без повторного playMusic, позиция подготовленного трека сохраняется (1,5 и 2,0 с); последний трек в режиме «один раз» переход не начинает; полоски на панели и в окне показывают проценты.'
);
-- +goose StatementEnd

